1.一个当前会话内容查询功能（好像最近已经被官方实现了）（等等deepseek官方那里有bug）搜索算法用的是精确子串 + Token 覆盖的混合策略，适合”用户查找”场景：精确匹配得 100 分，Token 全命中再加 30 分。这意味着你搜”之前那个报错”和搜”报错”都能命中同一条消息，但前者如果恰好是原文子串，会排在最前面。不需要向量检索——关键词匹配在这个场景下足够快、足够准。
中文分词用 bigram（双字组合）做中文分词。比如”搜索插件”会被拆成 搜、索、插、件、搜索、索插、插件。这样即使用户输入的关键词和原文不完全一致，也能通过 bigram 重叠匹配到。代码里用的是正则 [\u4e00-\u9fff\u3400-\u4dbf] 提取 CJK 字符，覆盖了基本汉字和扩展 A 区。
虚拟滚动处理提供了 loadAllMessages() 函数，但默认没有自动调用，因为它会强制滚动页面。如果你觉得搜索结果不全，可以在搜索前手动调用：
js&#x2F;&#x2F; 在控制台手动触发loadAllMessages().then(() &#x3D;&gt; console.log(‘加载完成，可以搜索了’));更好的做法是在面板里加一个”加载全部消息”按钮，但考虑到首次使用体验，默认不触发滚动。
增量索引MutationObserver 监听 document.body 的子节点变化，防抖 800ms 后调用 incrementalIndex()。这个函数只添加 ID 不在索引中的新消息，不会重建整个索引，性能开销很小。
会话切换通过监听 location.href 变化来检测会话切换。DeepSeek 是 SPA，切换会话不会刷新页面，所以需要监听 URL 变化。检测到变化后等 1 秒重建索引。
(function () {  ‘use strict’;
  &#x2F;&#x2F; &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; 配置 &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;  const CONFIG &#x3D; {    &#x2F;&#x2F; 消息选择器 —— 优先用 data 属性，如果不匹配则回退到 class 策略    MESSAGE_SELECTOR: ‘[data-message-author-role]’,    FALLBACK_SELECTOR: ‘div[class*&#x3D;”message”]’,    &#x2F;&#x2F; 搜索面板最大结果显示数    MAX_RESULTS: 30,    &#x2F;&#x2F; 搜索防抖延迟（毫秒）    DEBOUNCE_MS: 150,  };
  &#x2F;&#x2F; &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; 状态 &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;  const state &#x3D; {    messages: [],        &#x2F;&#x2F; { id, role, text, el }    index: new Map(),    &#x2F;&#x2F; id -&gt; message 对象    panelOpen: false,    currentQuery: ‘’,    resultElements: [],  &#x2F;&#x2F; 搜索结果对应的 DOM 元素    currentResultIndex: -1,  };
  &#x2F;&#x2F; &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; 工具函数 &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;
  &#x2F;** 简单字符串 hash，用于生成稳定 ID *&#x2F;  function simpleHash(str) {    let hash &#x3D; 0;    for (let i &#x3D; 0; i &lt; str.length; i++) {      const char &#x3D; str.charCodeAt(i);      hash &#x3D; (hash &lt;&lt; 5) - hash + char;      hash |&#x3D; 0;    }    return Math.abs(hash).toString(36);  }
  &#x2F;** 从 URL 提取会话 ID *&#x2F;  function getSessionId() {    const parts &#x3D; location.pathname.split(‘&#x2F;‘).filter(Boolean);    return parts[parts.length - 1] || ‘default’;  }
  &#x2F;** 中文分词：bigram + 英文单词 *&#x2F;  function tokenize(text) {    const tokens &#x3D; [];    const lower &#x3D; text.toLowerCase();
// 英文单词和数字
const wordMatches = lower.match(/[a-z0-9_]+/g);
if (wordMatches) tokens.push(...wordMatches);

// 中文字符 bigram
const cjkRegex = /[\u4e00-\u9fff\u3400-\u4dbf]/g;
const cjkChars = lower.match(cjkRegex);
if (cjkChars) {
  tokens.push(...cjkChars);
  for (let i = 0; i &lt; cjkChars.length - 1; i++) {
    tokens.push(cjkChars[i] + cjkChars[i + 1]);
  }
}

return tokens;

  }
  &#x2F;** 检测消息角色 *&#x2F;  function detectRole(el) {    &#x2F;&#x2F; 优先用 data 属性    const role &#x3D; el.dataset.messageAuthorRole;    if (role &#x3D;&#x3D;&#x3D; ‘user’ || role &#x3D;&#x3D;&#x3D; ‘assistant’) return role;
// 回退：根据 class 或文本特征判断
const className = el.className || &#39;&#39;;
if (className.includes(&#39;user&#39;) || className.includes(&#39;User&#39;)) return &#39;user&#39;;
if (className.includes(&#39;assistant&#39;) || className.includes(&#39;Assistant&#39;)) return &#39;assistant&#39;;

// 最后回退：用户消息通常较短
return el.innerText.length &lt; 300 ? &#39;user&#39; : &#39;assistant&#39;;

  }
  &#x2F;&#x2F; &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; 消息提取 &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;
  &#x2F;** 提取页面中所有已加载的消息 *&#x2F;  function extractMessages() {    let elements &#x3D; […document.querySelectorAll(CONFIG.MESSAGE_SELECTOR)];
// 如果主选择器没有匹配到，尝试回退
if (elements.length === 0) {
  elements = [...document.querySelectorAll(CONFIG.FALLBACK_SELECTOR)]
    .filter(el =&gt; {
      const rect = el.getBoundingClientRect();
      return rect.width &gt; 300 &amp;&amp; el.innerText.trim().length &gt; 5;
    });
}

// 去重：如果父元素和子元素都匹配，只保留最深的
const deduped = elements.filter(el =&gt; {
  return !elements.some(other =&gt; other !== el &amp;&amp; other.contains(el));
});

// 按 DOM 顺序排列
deduped.sort((a, b) =&gt; {
  const pos = a.compareDocumentPosition(b);
  if (pos &amp; Node.DOCUMENT_POSITION_FOLLOWING) return -1;
  if (pos &amp; Node.DOCUMENT_POSITION_PRECEDING) return 1;
  return 0;
});

return deduped.map((el, i) =&gt; {
  const text = el.innerText.trim();
  const id = `msg-${getSessionId()}-${i}-${simpleHash(text.slice(0, 100))}`;
  return {
    id,
    role: detectRole(el),
    text,
    el,
  };
});

  }
  &#x2F;** 重建索引 *&#x2F;  function rebuildIndex() {    state.messages &#x3D; extractMessages();    state.index.clear();    state.messages.forEach(msg &#x3D;&gt; state.index.set(msg.id, msg));    updateResultCount();  }
  &#x2F;** 增量索引：只添加新消息 *&#x2F;  function incrementalIndex() {    const current &#x3D; extractMessages();    let added &#x3D; 0;
current.forEach(msg =&gt; {
  if (!state.index.has(msg.id)) {
    state.messages.push(msg);
    state.index.set(msg.id, msg);
    added++;
  }
});

if (added &gt; 0) {
  // 重新排序，保持 DOM 顺序
  state.messages.sort((a, b) =&gt; {
    const pos = a.el.compareDocumentPosition(b.el);
    if (pos &amp; Node.DOCUMENT_POSITION_FOLLOWING) return -1;
    if (pos &amp; Node.DOCUMENT_POSITION_PRECEDING) return 1;
    return 0;
  });
}

  }
  &#x2F;&#x2F; &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; 搜索逻辑 &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;
  &#x2F;** 执行搜索 *&#x2F;  function search(query) {    if (!query || query.trim().length &lt; 1) {      renderResults([]);      return;    }
const queryTokens = tokenize(query);
if (queryTokens.length === 0) {
  renderResults([]);
  return;
}

const queryLower = query.toLowerCase();

// 对每条消息计算得分
const scored = state.messages.map(msg =&gt; {
  const textLower = msg.text.toLowerCase();
  const textTokens = tokenize(msg.text);
  const tokenSet = new Set(textTokens);

  let score = 0;

  // 1. 精确子串匹配（最高权重）
  if (textLower.includes(queryLower)) {
    score += 100;
    // 如果在开头附近匹配，额外加分
    const idx = textLower.indexOf(queryLower);
    if (idx &lt; 50) score += 20;
  }

  // 2. Token 匹配
  let matchedTokens = 0;
  for (const token of queryTokens) {
    if (tokenSet.has(token)) {
      matchedTokens++;
      score += 10;
    }
  }

  // 3. Token 覆盖率奖励
  if (queryTokens.length &gt; 1) {
    const coverage = matchedTokens / queryTokens.length;
    if (coverage === 1) score += 30; // 全部命中
    else if (coverage &gt;= 0.5) score += 10;
  }

  // 4. 角色过滤奖励（用户提问通常更需要被搜索到）
  if (msg.role === &#39;user&#39; &amp;&amp; score &gt; 0) score += 5;

  return { msg, score };
});

// 过滤掉得分为 0 的，排序取 top
const results = scored
  .filter(item =&gt; item.score &gt; 0)
  .sort((a, b) =&gt; b.score - a.score)
  .slice(0, CONFIG.MAX_RESULTS)
  .map(item =&gt; item.msg);

renderResults(results, query);

  }
  &#x2F;&#x2F; &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; UI 构建 &#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;
  &#x2F;** 创建搜索面板 DOM *&#x2F;  function createPanel() {    const panel &#x3D; document.createElement(‘div’);    panel.id &#x3D; ‘ds-search-panel’;    panel.innerHTML &#x3D;       &lt;div class=&quot;ds-search-header&quot;&gt;         &lt;input id=&quot;ds-search-input&quot; type=&quot;text&quot; placeholder=&quot;搜索当前会话...&quot; autocomplete=&quot;off&quot; /&gt;         &lt;span id=&quot;ds-search-count&quot;&gt;&lt;/span&gt;         &lt;button id=&quot;ds-search-close&quot; title=&quot;关闭&quot;&gt;✕&lt;/button&gt;       &lt;/div&gt;       &lt;div id=&quot;ds-search-results&quot;&gt;&lt;/div&gt;       &lt;div class=&quot;ds-search-footer&quot;&gt;         &lt;span&gt;Enter 跳转到下一条 · Shift+Enter 上一条 · Esc 关闭&lt;/span&gt;       &lt;/div&gt;    ;
// 注入样式
const style = document.createElement(&#39;style&#39;);
style.textContent = `
  #ds-search-panel {
    position: fixed;
    top: 60px;
    right: 20px;
    width: 420px;
    max-height: 70vh;
    background: var(--ds-bg-color, #1e1e2e);
    color: var(--ds-text-color, #cdd6f4);
    border: 1px solid rgba(128, 128, 128, 0.3);
    border-radius: 12px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
    z-index: 99999;
    display: none;
    flex-direction: column;
    font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, sans-serif;
    font-size: 14px;
    overflow: hidden;
    backdrop-filter: blur(12px);
  }
  #ds-search-panel.open { display: flex; }

  .ds-search-header {
    display: flex;
    align-items: center;
    padding: 10px 12px;
    border-bottom: 1px solid rgba(128, 128, 128, 0.2);
    gap: 8px;
  }
  #ds-search-input {
    flex: 1;
    background: rgba(128, 128, 128, 0.15);
    border: 1px solid rgba(128, 128, 128, 0.2);
    border-radius: 6px;
    padding: 8px 10px;
    color: inherit;
    font-size: 14px;
    outline: none;
  }
  #ds-search-input:focus {
    border-color: #7c3aed;
    box-shadow: 0 0 0 2px rgba(124, 58, 237, 0.2);
  }
  #ds-search-count {
    font-size: 12px;
    opacity: 0.6;
    white-space: nowrap;
  }
  #ds-search-close {
    background: none;
    border: none;
    color: inherit;
    cursor: pointer;
    font-size: 16px;
    opacity: 0.6;
    padding: 4px;
  }
  #ds-search-close:hover { opacity: 1; }

  #ds-search-results {
    overflow-y: auto;
    flex: 1;
    padding: 4px;
  }

  .ds-result-item {
    padding: 8px 10px;
    border-radius: 8px;
    cursor: pointer;
    margin-bottom: 2px;
    transition: background 0.15s;
  }
  .ds-result-item:hover,
  .ds-result-item.active {
    background: rgba(124, 58, 237, 0.15);
  }
  .ds-result-role {
    font-size: 11px;
    font-weight: 600;
    opacity: 0.5;
    margin-bottom: 3px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }
  .ds-result-snippet {
    font-size: 13px;
    line-height: 1.5;
    opacity: 0.85;
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
  .ds-result-snippet mark {
    background: rgba(124, 58, 237, 0.4);
    color: inherit;
    border-radius: 2px;
    padding: 0 2px;
  }
  .ds-result-empty {
    padding: 20px;
    text-align: center;
    opacity: 0.5;
    font-size: 13px;
  }

  .ds-search-footer {
    padding: 6px 12px;
    border-top: 1px solid rgba(128, 128, 128, 0.2);
    font-size: 11px;
    opacity: 0.4;
    text-align: center;
  }

  /* 消息高亮动画 */
  .ds-search-hit {
    animation: ds-hit-flash 1.5s ease-out !important;
    outline: 2px solid #7c3aed !important;
    outline-offset: 2px;
    border-radius: 8px;
  }
  @keyframes ds-hit-flash {
    0% { outline-color: #7c3aed; outline-width: 4px; }
    100% { outline-color: transparent; outline-width: 2px; }
  }

  /* 悬浮按钮 */
  #ds-search-fab {
    position: fixed;
    bottom: 100px;
    right: 24px;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: #7c3aed;
    color: #fff;
    border: none;
    cursor: pointer;
    font-size: 18px;
    z-index: 99998;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.4);
    transition: transform 0.15s, box-shadow 0.15s;
  }
  #ds-search-fab:hover {
    transform: scale(1.1);
    box-shadow: 0 6px 16px rgba(124, 58, 237, 0.5);
  }
`;

document.head.appendChild(style);
document.body.appendChild(panel);

// 悬浮按钮
const fab = document.createElement(&#39;button&#39;);
fab.id = &#39;ds-search-fab&#39;;
fab.title = &#39;搜索会话 (Alt+K)&#39;;
fab.textContent = &#39;🔍&#39;;
document.body.appendChild(fab);

// ==================== 事件绑定 ====================

const input = panel.querySelector(&#39;#ds-search-input&#39;);
const resultsEl = panel.querySelector(&#39;#ds-search-results&#39;);
const closeBtn = panel.querySelector(&#39;#ds-search-close&#39;);

// 输入防抖
let debounceTimer;
input.addEventListener(&#39;input&#39;, () =&gt; {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(() =&gt; {
    state.currentQuery = input.value;
    search(input.value);
  }, CONFIG.DEBOUNCE_MS);
});

// 键盘导航
input.addEventListener(&#39;keydown&#39;, (e) =&gt; {
  if (e.key === &#39;Enter&#39;) {
    e.preventDefault();
    if (e.shiftKey) navigateResult(-1);
    else navigateResult(1);
  } else if (e.key === &#39;Escape&#39;) {
    closePanel();
  }
});

// 关闭按钮
closeBtn.addEventListener(&#39;click&#39;, closePanel);
fab.addEventListener(&#39;click&#39;, togglePanel);

// 全局快捷键 Alt+K
document.addEventListener(&#39;keydown&#39;, (e) =&gt; {
  if (e.altKey &amp;&amp; e.key === &#39;k&#39;) {
    e.preventDefault();
    togglePanel();
  }
  if (e.key === &#39;Escape&#39; &amp;&amp; state.panelOpen) {
    closePanel();
  }
});

// 点击面板外部关闭（可选，注释掉以免误关）
// document.addEventListener(&#39;click&#39;, (e) =&gt; {
//   if (state.panelOpen &amp;&amp; !panel.contains(e.target) &amp;&amp; e.target !== fab) {
//     closePanel();
//   }
// });

  }
  &#x2F;** 打开&#x2F;关闭面板 *&#x2F;  function togglePanel() {    const panel &#x3D; document.getElementById(‘ds-search-panel’);    if (!panel) return;
if (state.panelOpen) {
  closePanel();
} else {
  panel.classList.add(&#39;open&#39;);
  state.panelOpen = true;
  const input = document.getElementById(&#39;ds-search-input&#39;);
  input.value = &#39;&#39;;
  input.focus();
  // 打开时重建索引，确保包含最新消息
  rebuildIndex();
  renderResults([]);
}

  }
  function closePanel() {    const panel &#x3D; document.getElementById(‘ds-search-panel’);    if (panel) panel.classList.remove(‘open’);    state.panelOpen &#x3D; false;    state.resultElements &#x3D; [];    state.currentResultIndex &#x3D; -1;  }
  &#x2F;** 渲染搜索结果 *&#x2F;  function renderResults(results, query) {    const resultsEl &#x3D; document.getElementById(‘ds-search-results’);    if (!resultsEl) return;
state.resultElements = results.map(r =&gt; r.el);
state.currentResultIndex = -1;

if (results.length === 0) {
  resultsEl.innerHTML = query
    ? &#39;&lt;div class=&quot;ds-result-empty&quot;&gt;没有找到匹配的消息&lt;/div&gt;&#39;
    : &#39;&lt;div class=&quot;ds-result-empty&quot;&gt;输入关键词开始搜索&lt;/div&gt;&#39;;
  updateResultCount();
  return;
}

resultsEl.innerHTML = results.map((msg, i) =&gt; {
  // 生成高亮片段
  let snippet = msg.text.slice(0, 200);
  if (query) {
    const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, &#39;\\$&amp;&#39;);
    snippet = snippet.replace(
      new RegExp(`(${escaped})`, &#39;gi&#39;),
      &#39;&lt;mark&gt;$1&lt;/mark&gt;&#39;
    );
  }
  const roleLabel = msg.role === &#39;user&#39; ? &#39;你&#39; : &#39;AI&#39;;

  return `
    &lt;div class=&quot;ds-result-item&quot; data-index=&quot;${i}&quot;&gt;
      &lt;div class=&quot;ds-result-role&quot;&gt;${roleLabel}&lt;/div&gt;
      &lt;div class=&quot;ds-result-snippet&quot;&gt;${snippet}&lt;/div&gt;
    &lt;/div&gt;
  `;
}).join(&#39;&#39;);

// 绑定点击事件
resultsEl.querySelectorAll(&#39;.ds-result-item&#39;).forEach(item =&gt; {
  item.addEventListener(&#39;click&#39;, () =&gt; {
    const idx = parseInt(item.dataset.index, 10);
    jumpToResult(idx);
  });
});

updateResultCount();

  }
  &#x2F;** 更新结果计数显示 *&#x2F;  function updateResultCount() {    const countEl &#x3D; document.getElementById(‘ds-search-count’);    if (!countEl) return;    const total &#x3D; state.resultElements.length;    if (state.currentResultIndex &gt;&#x3D; 0 &amp;&amp; total &gt; 0) {      countEl.textContent &#x3D; ${state.currentResultIndex + 1}/${total};    } else {      countEl.textContent &#x3D; total &gt; 0 ? ${total} 条 : ‘’;    }  }
  &#x2F;** 导航到上一条&#x2F;下一条结果 *&#x2F;  function navigateResult(direction) {    const total &#x3D; state.resultElements.length;    if (total &#x3D;&#x3D;&#x3D; 0) return;
state.currentResultIndex += direction;
if (state.currentResultIndex &lt; 0) state.currentResultIndex = total - 1;
if (state.currentResultIndex &gt;= total) state.currentResultIndex = 0;

// 更新 UI 选中态
document.querySelectorAll(&#39;.ds-result-item&#39;).forEach((item, i) =&gt; {
  item.classList.toggle(&#39;active&#39;, i === state.currentResultIndex);
});

// 滚动到对应消息
